"""Seed intake summary for Wardley Seed Bank.

Sweeps the launch directory for intake-*.json exports, totals the
packets per species and prints the species at or above the storage
threshold to standard output.
"""
import glob
import json
import os


def main() -> None:
    totals = {}
    pattern = os.path.join(os.getcwd(), "**", "intake-*.json")
    for path in sorted(glob.glob(pattern, recursive=True)):
        with open(path, encoding="utf-8") as handle:
            export = json.load(handle)
        for record in export.get("intake", []):
            state = record.get("state", "")
            if state == "discarded":
                continue
            amount = int(record.get("packets", 0))
            if state == "returned":
                amount = -amount
            code = record.get("species", "")
            totals[code] = totals.get(code, 0) + amount
    listed = [(code, total) for code, total in totals.items() if total >= 100]
    listed.sort(key=lambda item: (-item[1], item[0]))
    print("species_code,total_packets")
    for code, total in listed:
        print("%s,%d" % (code, total))


if __name__ == "__main__":
    main()

